function maxSumAfterFlips(nums: number[], k: number): number {
  const a = [...nums];
  for (let f = 0; f < k; f++) {
    let m = 0;
    for (let i = 1; i < a.length; i++) if (a[i] < a[m]) m = i;
    a[m] = -a[m];
  }
  return a.reduce((s, x) => s + x, 0);
}

