function maxSumAfterFlips(nums: number[], k: number): number {
  const a = [...nums].sort((x, y) => x - y);
  for (let i = 0; i < a.length && k > 0 && a[i] < 0; i++) {
    a[i] = -a[i];
    k--;
  }
  let sum = 0, smallest = Infinity;
  for (const x of a) {
    sum += x;
    smallest = Math.min(smallest, Math.abs(x));
  }
  return k % 2 === 1 ? sum - 2 * smallest : sum;
}

