    def maxSumAfterFlips(self, nums: List[int], k: int) -> int:
        a = sorted(nums)
        for i in range(len(a)):
            if k == 0 or a[i] >= 0:
                break
            a[i] = -a[i]
            k -= 1
        total = sum(a)
        return total - 2 * min(abs(x) for x in a) if k % 2 else total

